command:
$ErrorActionPreference = 'Stop'
function Invoke-Checked([string]$Label, [scriptblock]$Action) { Write-Host "=== $Label ==="; & $Action; if ($LASTEXITCODE -ne 0) { throw "$Label failed with exit $LASTEXITCODE" } }
$head = (git rev-parse HEAD).Trim()
Write-Host "validation_head=$head"
Invoke-Checked 'Compile v32 v33 v34 and entrypoint' { python -m py_compile .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v32.py .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v32_selftest.py .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v33.py .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v33_selftest.py .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v34.py .github/dcoir_review/scripts/dcoir_review_required_runtime_patch_v34_selftest.py .github/dcoir_review/scripts/dcoir_review/entrypoint.py }
Invoke-Checked 'Pareto context selftest' { python .github/dcoir_review/scripts/openrouter_pr_review_pareto_context_selftest.py }
$patchTests = Get-ChildItem '.github/dcoir_review/scripts' -Filter 'dcoir_review_required_runtime_patch_v*_selftest.py' | Sort-Object Name
foreach ($test in $patchTests) { Invoke-Checked ("Runtime patch selftest: " + $test.Name) { python $test.FullName } }
Invoke-Checked 'DCOIR precision regression' { python .github/dcoir_review/scripts/dcoir_review_precision_regression_selftest.py }
Invoke-Checked 'Hardened reviewer selftest' { python .github/dcoir_review/scripts/openrouter_pr_review_hardened_selftest.py }
Invoke-Checked 'Quality recovery selftest' { python .github/dcoir_review/scripts/openrouter_pr_review_quality_recovery_selftest.py }
Invoke-Checked 'Summary problem selftest' { python .github/dcoir_review/scripts/openrouter_pr_review_summary_problem_selftest.py }
Invoke-Checked 'CodeQL workflow validator' { python .github/dcoir_review/scripts/validate-codeql-security-workflow.py }
Write-Host 'dcoir_v34_validation=pass'
